// Precompute HINTS for logs-through-the-platform-logger: the print-style and logger calls ADDED in
// application code, per language, and whether a bounded search of the checkout matches a logger. The
// closed list of print shapes and logger shapes per language mirrors the criteria; whether a print is the
// program's output (a CLI, a script) or a shipped debugging line is the review's to decide from the file.
import { grep } from "../lib/grep.ts";
import { countLabel, scanAddedLines, type SourcePattern } from "../lib/source-scan.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

interface Shapes {
	print: SourcePattern[];
	logger: SourcePattern[];
}

const SCRIPTING: Shapes = {
	print: [["console.*", /\bconsole\.(?:log|debug|info|warn|error)\s*\(/u]],
	logger: [["logger", /\b(?:log|logger)\.(?:trace|debug|info|warn|error|fatal)\s*\(/u]],
};

// The Apple system log: NSLog and NSLogv write to it, as the os_log family does.
const APPLE_SYSTEM_LOG: SourcePattern[] = [
	["os_log", /\bos_log(?:_(?:info|debug|error|fault))?\s*\(/u],
	["NSLog", /\bNSLogv?\s*\(/u],
];

// android.util.Log at any level and whatever its tag, and Timber over it. A bare `Log.` is read by name:
// the import that makes it android.util.Log is the review's to confirm.
const ANDROID_LOG: SourcePattern[] = [
	["android.util.Log", /\b(?:android\.util\.)?Log\.(?:v|d|i|w|e|wtf)\s*\(/u],
	["Timber", /\bTimber\.(?:v|d|i|w|e|wtf)\s*\(/u],
];

// language -> the print-style shapes and the logger shapes the criteria list for it.
const DIAGNOSTICS: Record<string, Shapes> = {
	swift: {
		print: [
			["print(", /(?:^|[^\w.])print\s*\(/u],
			["debugPrint(", /\bdebugPrint\s*\(/u],
			["dump(", /(?:^|[^\w.])dump\s*\(/u],
		],
		logger: [
			[
				"Logger",
				/\bLogger\s*\(|\b(?:logger|Logger\.shared)\.(?:trace|debug|info|notice|warning|error|critical|fault|log)\s*\(/u,
			],
			...APPLE_SYSTEM_LOG,
		],
	},
	"objective-c": {
		print: [["printf(", /\bprintf\s*\(/u]],
		logger: APPLE_SYSTEM_LOG,
	},
	kotlin: {
		print: [["println(", /(?:^|[^\w.])println?\s*\(/u]],
		logger: [...ANDROID_LOG, ["logger", /\blog(?:ger)?\.(?:trace|debug|info|warn|error)\s*\(/u]],
	},
	java: {
		print: [
			["System.out/err", /\bSystem\.(?:out|err)\.print/u],
			["printStackTrace()", /\.printStackTrace\s*\(/u],
		],
		logger: [
			...ANDROID_LOG,
			["logger", /\b(?:log|logger|LOG|LOGGER)\.(?:trace|debug|info|warn|error|severe|fine)\s*\(/u],
		],
	},
	typescript: SCRIPTING,
	javascript: SCRIPTING,
	python: {
		print: [["print(", /(?:^|[^\w.])print\s*\(/u]],
		logger: [
			[
				"logging",
				/\b(?:logging|logger|log)\.(?:debug|info|warning|error|exception|critical)\s*\(/u,
			],
		],
	},
};

/** Where a print is the program's output rather than a diagnostic: the criteria's exemptions, by path. */
const TOOL_PATH =
	/(?:^|\/)(?:scripts?|tools?|bin|cli|Scripts|fastlane|ci)\/|\.(?:sh|mjs|cjs)$|(?:^|\/)main\.(?:py|ts|js)$|Playground|\.playground\//u;

export default async function logsThroughThePlatformLogger(
	repoPath: string,
	diffFiles: Map<string, DiffFile>,
	_metadata: PullRequestMetadata,
) {
	const hints: Hint[] = [];
	let prints = 0;
	let loggers = 0;
	let filesScanned = 0;
	let linesAdded = 0;
	for (const [language, shapes] of Object.entries(DIAGNOSTICS)) {
		const scan = await scanAddedLines(repoPath, diffFiles, {
			languages: [language],
			patterns: [...shapes.print, ...shapes.logger],
			maxHints: 40,
		});
		filesScanned += scan.filesScanned;
		linesAdded += scan.linesAdded;
		prints += shapes.print.reduce((sum, [label]) => sum + countLabel(scan, label), 0);
		loggers += shapes.logger.reduce((sum, [label]) => sum + countLabel(scan, label), 0);
		for (const hint of scan.hints) {
			const isPrint = shapes.print.some(([label]) => label === hint.pattern);
			hints.push({
				...hint,
				pattern: `${language}:${hint.pattern}`,
				flags: {
					...hint.flags,
					kind: isPrint ? "print" : "logger",
					toolPath: TOOL_PATH.test(hint.file),
				},
			});
		}
	}
	const listed = hints.slice(0, 40);
	const printsInToolPaths = listed.filter(
		(h) => h.flags.kind === "print" && h.flags.toolPath === true,
	).length;
	// Whether a bounded lexical search of the checkout matches a logger definition, import or native call.
	const existing = await grep(
		String.raw`\bLogger\s*\(|\bos_log|\bNSLogv?\s*\(|import android\.util\.Log\b|\bTimber\b|LoggerFactory|import logging|from 'pino'|from "pino"|winston`,
		repoPath,
		{ maxResults: 5 },
	);
	const directions: string[] =
		prints + loggers > listed.length
			? [
					`${String(prints + loggers)} diagnostic line(s) added; ${String(listed.length)} are listed. The counts by kind cover every line; the tool-path count covers only the listed rows.`,
				]
			: [];
	if (prints > 0) {
		directions.push(
			`${prints} print-style call(s) added (${printsInToolPaths} listed under a tool or script path) against ${loggers} logger call(s); ${existing.length > 0 ? `the checkout matches a logger (${existing[0]?.file ?? ""})` : "a bounded search of the checkout matched no logger definition, which does not show there is none"}. Read each print's file to decide whether it is the program's output, a DEBUG-only block or a shipped diagnostic.`,
		);
	} else if (loggers > 0) {
		directions.push(`${loggers} logger call(s) added and no print-style call.`);
	}
	return {
		hints: listed,
		metrics: {
			printsAdded: prints,
			loggerCallsAdded: loggers,
			printsInToolPaths,
			checkoutHasLogger: existing.length > 0 ? 1 : 0,
			filesScanned,
			linesAdded,
		},
		directions,
	};
}

// Precompute FACTS for validates-inputs-and-edge-cases-at-the-boundary: the added lines of source code
// that hold a construct which can fail or mislead on an edge value — a subscript or slice, a division by
// a name, a parse the language does not force the author to handle, an extreme sentinel, a payload
// decode, a request's own input — across languages. A row marks where a consuming site may be, never an
// observation: whether its value comes from outside the local logic, and what already handles its bad case,
// is read from the code, and the criteria decide. String-literal text and comments are not scanned; a
// lookup or parse whose result the language makes optional is not listed, and a crash operator the author
// wrote (`!`, `try!`, `unwrap()`) is the crash practice's. Adding a language = adding a row.
import { codeLines, isCommentLine } from "../lib/declarations.ts";
import { isTestPath, languageOf } from "../lib/languages.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

const COMMON: [string, RegExp][] = [
	// `items[i]`, `cast[0..<2]`; not a lookup already made safe (`dict[k] ?? d`, `[k, default: 0]`,
	// `ns[k] as? T`) nor an assignment target.
	[
		"subscript or slice",
		/[A-Za-z0-9_)\]]\[(?![^\]]*\bdefault:)[^\]]+\](?!\s*(?:\?\?|as\?|=(?!=)))/u,
	],
	// A divisor that is a name or a call; a literal divisor cannot be zero.
	["division or remainder by a name", /[A-Za-z0-9_)\]]\s*[/%](?![/*=])\s*[A-Za-z_(]/u],
	// The seed of a minimum, a maximum or a fallback that can reach output unchanged.
	[
		"extreme sentinel",
		/\b(?:U?Int\d*|Double|Float|CGFloat)\.(?:max|min|infinity|greatestFiniteMagnitude)\b|\b(?:Integer|Long|Double|Float)\.(?:MAX|MIN)_VALUE\b|\bNumber\.(?:MAX|MIN)_(?:SAFE_INTEGER|VALUE)\b|\bsys\.maxsize\b|\bmath\.inf\b/u,
	],
];

// language key -> [label, regex] of edge constructs in added code, beside COMMON.
const LANG_PATTERNS: Record<string, [string, RegExp][]> = {
	// `Int(text)`, `Double(s)`, `.first`, `dict[key]` return Optionals the compiler makes the author handle.
	swift: [["payload decode", /(?<![Cc]ontainer)\.decode\s*\(/u]],
	typescript: [
		["parseInt/parseFloat", /\bparse(?:Int|Float)\s*\(/u],
		["Number(...) parse", /\bNumber\s*\(/u],
		["JSON.parse", /\bJSON\.parse\s*\(/u],
	],
	javascript: [
		["parseInt/parseFloat", /\bparse(?:Int|Float)\s*\(/u],
		["Number(...) parse", /\bNumber\s*\(/u],
		["JSON.parse", /\bJSON\.parse\s*\(/u],
	],
	python: [
		["int()/float() parse", /\b(?:int|float)\s*\(/u],
		["json.loads", /\bjson\.loads\s*\(/u],
		[".pop()", /\.pop\s*\(/u],
		["next(...)", /\bnext\s*\(/u],
	],
	go: [
		["strconv parse", /\bstrconv\.(?:Atoi|Parse[A-Za-z]+)\s*\(/u],
		["json.Unmarshal", /\bjson\.Unmarshal\s*\(/u],
	],
	java: [
		[".get(i) access", /\.get\s*\(\s*[A-Za-z_]/u],
		["Integer/Long/Double.parse", /\b(?:Integer|Long|Double|Float)\.parse[A-Za-z]+\s*\(/u],
		["valueOf parse", /\b(?:Integer|Long|Double|Float)\.valueOf\s*\(/u],
		[".charAt/.substring", /\.(?:charAt|substring)\s*\(/u],
	],
	kotlin: [
		["toInt/toDouble parse", /\.to(?:Int|Long|Double|Float)\s*\(\s*\)/u],
		[".first()/.last()", /\.(?:first|last)\s*\(\s*\)/u],
	],
	rust: [],
	ruby: [
		["JSON.parse", /\bJSON\.parse\s*\(/u],
		[".fetch", /\.fetch\s*\(/u],
	],
	c: [
		["atoi/strtol parse", /\b(?:atoi|atol|atof|strtol|strtod)\s*\(/u],
		["pointer deref *", /(?:^|[^\w)])\*[A-Za-z_]/u],
	],
	csharp: [
		[
			"int.Parse/Convert",
			/\b(?:int|long|double|float|decimal|Int32|Int64|Convert)\.(?:Parse|To[A-Za-z]+)\s*\(/u,
		],
		["JsonSerializer.Deserialize", /\.Deserialize\s*\(/u],
		[".First()/.Last()/.Single()", /\.(?:First|Last|Single)\s*\(\s*\)/u],
	],
};

// Where a request's own input enters a handler: the criteria's "a request param, body or header".
const REQUEST_INPUT: Record<string, RegExp> = {
	java: /@(?:RequestParam|PathVariable|RequestBody|RequestHeader)\b/u,
	kotlin: /@(?:RequestParam|PathVariable|RequestBody|RequestHeader)\b/u,
	typescript: /\breq(?:uest)?\.(?:params|query|body|headers)\b/u,
	javascript: /\breq(?:uest)?\.(?:params|query|body|headers)\b/u,
	python: /\brequest\.(?:args|form|json|GET|POST|query_params|data)\b/u,
	go: /\br\.(?:URL\.Query|FormValue|PostFormValue|PathValue)\b/u,
	swift: /\breq\.(?:parameters|query|content)\b/u,
};

export default function validatesInputsAndEdgeCasesAtTheBoundary(
	_repo: string,
	diffFiles: Map<string, DiffFile>,
	_m: PullRequestMetadata,
) {
	const hints: Hint[] = [];
	const byKind: Record<string, number> = {};
	let filesScanned = 0;
	let linesScanned = 0;

	for (const [path, df] of diffFiles) {
		const lang = languageOf(path);
		const own = lang === null ? undefined : LANG_PATTERNS[lang];
		// A test's fixtures are not a boundary.
		if (lang === null || !own || isTestPath(path)) {
			continue;
		}
		const request = REQUEST_INPUT[lang];
		const patterns: [string, RegExp][] =
			request === undefined ? [...COMMON, ...own] : [["request input", request], ...COMMON, ...own];
		const code = codeLines(lang, df.addedLines);
		filesScanned += 1;
		for (const [line, content] of df.addedLines) {
			if (isCommentLine(content, lang)) {
				continue;
			}
			linesScanned += 1;
			const labels = patterns
				.filter(([, re]) => re.test(code.get(line) ?? ""))
				.map(([name]) => name);
			if (labels.length === 0) {
				continue;
			}
			for (const label of labels) {
				byKind[label] = (byKind[label] ?? 0) + 1;
			}
			hints.push({
				file: path,
				line,
				pattern: `${lang}:${labels.join(" + ")}`,
				context: content.trim().slice(0, 160),
				inDiff: true,
				flags: {},
			});
		}
	}

	const kinds = Object.entries(byKind)
		.map(([kind, count]) => `${String(count)} ${kind}`)
		.join(", ");
	const directions =
		hints.length > 0
			? [
					`${hints.length} added line(s) hold a construct that can fail or mislead on an edge value (${kinds}). String-literal text, comments and test files were not scanned; lookups and parses whose result the language makes optional, and crash operators, are not listed. A listed line marks where a consuming site may be, not an observation: whether its value comes from outside the local logic, and what already handles its bad case, is read from the code.`,
				]
			: [];

	return {
		hints: hints.slice(0, 40),
		metrics: {
			edgeConstructLines: hints.length,
			filesScanned,
			linesScanned,
			...byKind,
		},
		directions,
	};
}
